css:
.masthead { font-family: Georgia, serif; max-width: 360px; color: #222; }
.badge { display: inline-block; background: #f97316; color: white; padding: 2px 10px; border-radius: 999px; font-family: sans-serif; font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; }
.masthead h1 { font-size: 1.5rem; margin: 8px 0 6px; }
.lede { font-size: 1.05rem; color: #444; }
.meta { color: #999; font-size: 0.85rem; }
.masthead hr { border: none; border-top: 1px solid #ddd; margin: 10px 0; }
.masthead a { color: #f97316; }

.badge {
  display: {{inline-block}};
  background: #f97316;
  color: white;
  padding: 6px 14px;
  border-radius: 999px;
  font-weight: {{700}};
  font-size: 13px;
  letter-spacing: {{0.08em}};
  text-transform: {{uppercase}};
}

.signup { font-family: sans-serif; max-width: 280px; }
.signup input {
  width: 100%;
  padding: 8px 10px;
  border: {{1px solid #ddd}};
  border-radius: 8px;
  box-sizing: border-box;
}
.signup button {
  margin-top: 8px;
  border: none;
  border-radius: 999px;
  background: #f97316;
  color: white;
  padding: 8px 18px;
  cursor: pointer;
}
